// build-published-fonts.mjs — regenerate published-fonts.js from the woff2
// files in this folder.
//
//   node Tools/schedule/fonts/build-published-fonts.mjs
//
// Why a generated file rather than a link tag: a published Schedule Browser
// is a single HTML file a teacher downloads and emails to staff. It has no
// folder next to it, so it cannot reference these woff2 files by path, and it
// must not reference fonts.googleapis.com. The only remaining way to make it
// look the same on every machine is to carry the font bytes inside it.
//
// The generator loads published-fonts.js with a plain script tag and pastes
// the string into the <style> block of every file it publishes. If the file is
// missing, brBuildPublishedHTML() falls back to a system font stack rather
// than a hotlink — see the FONT_CSS comment in schedule-visualizer.html.
//
// Only the faces the published stylesheet uses are here. That is a smaller set
// than the generator's own fonts.css: a published file has no DM Sans or DM
// Mono in it, and every Fraunces rule in BR_CSS sets weight 600.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));

const FACES = [
  { family: 'Fraunces',    weight: 600, file: 'fraunces-latin-600-normal.woff2' },
  { family: 'Public Sans', weight: 400, file: 'public-sans-latin-400-normal.woff2' },
  { family: 'Public Sans', weight: 500, file: 'public-sans-latin-500-normal.woff2' },
  { family: 'Public Sans', weight: 600, file: 'public-sans-latin-600-normal.woff2' },
  { family: 'Public Sans', weight: 700, file: 'public-sans-latin-700-normal.woff2' },
];

let raw = 0;
const rules = FACES.map(f => {
  const bytes = fs.readFileSync(path.join(HERE, f.file));
  raw += bytes.length;
  // font-display:block, not swap. A published file is often opened from a
  // local disk where the data URI resolves instantly; block avoids a flash of
  // fallback text on the one paint where it does not.
  return `@font-face{font-family:'${f.family}';font-style:normal;font-weight:${f.weight};` +
         `font-display:block;src:url(data:font/woff2;base64,${bytes.toString('base64')}) format('woff2')}`;
}).join('\n');

const out =
`/* published-fonts.js — GENERATED by build-published-fonts.mjs. Do not edit.
   ${FACES.length} faces, ${raw} bytes of woff2, base64 into a single CSS string
   that brBuildPublishedHTML() inlines into every file it publishes. */
window.BR_PUBLISHED_FONT_CSS = ${JSON.stringify(rules)};
`;

const dest = path.join(HERE, 'published-fonts.js');
fs.writeFileSync(dest, out, 'utf8');
console.log(`wrote ${path.basename(dest)} — ${FACES.length} faces, ` +
            `${raw} bytes woff2 -> ${out.length} bytes of JS ` +
            `(+${(out.length / raw * 100 - 100).toFixed(1)}% base64 overhead)`);
